import{b as e,Y as t,O as s,g as a,l as o}from"./chunks/framework.DcaUmd3X.js";const P=JSON.parse('{"title":"软件测试","description":"","frontmatter":{"layout":"page","title":"软件测试","aside":false,"mindmap":"# 软件测试\\n\\n## 测试基础\\n### 核心概念\\n- 什么是测试（验证 vs 确认）\\n  - 验证（Verification） — \\"我们做对了吗？\\" 检查产品是否符合规格说明书，是静态的、过程导向的。\\n  - 确认（Validation） — \\"我们做了对的东西吗？\\" 检查产品是否满足用户真实需求，是动态的、结果导向的\\n- 测试目标（找Bug / 评估质量 / 降低风险）\\n  - 找 Bug：最直接的目的——发现缺陷，越早越省钱\\n  - 评估质量：给出软件质量状态的客观信息，辅助决策\\"能不能上线\\"\\n  - 降低风险：识别并缓解潜在的质量风险，尤其是涉及安全、资金、合规的场景\\n- 测试七项基本原则（ISTQB）\\n  - 测试说明缺陷的存在，而非不存在 — 测试只能证明\\"有问题\\"，永远不能证明\\"没问题\\"。过了再多的用例也不等于零缺陷。\\n  - 穷尽测试是不可能的 — 除了极其简单的场景，不可能测完所有输入组合。所以要靠风险优先级和测试设计技术来取舍。\\n  - 尽早测试 — 缺陷发现越晚修复成本越高（需求阶段修一个误解的成本 vs 上线后发现 Bug 的成本，差几个数量级）。这就是 Shift-Left 的思想来源。\\n  - 缺陷集群效应 — 大部分缺陷集中在少数模块中。测试资源应该向\\"重灾区\\"倾斜，而不是均匀铺开。\\n  - 杀虫剂悖论 — 反复用同一组用例，就像反复喷同一种农药，Bug 会产生\\"抗药性\\"。用例需要持续维护和更新。\\n  - 测试依赖于上下文 — 银行系统和游戏 App 的测试策略完全不同。没有\\"通用\\"的测试方案，只有适配业务的方案。\\n  - 不存在缺陷的谬论 — 即使修完了所有 Bug，如果产品压根没人用、不符合用户预期，也是失败的。测试不仅要关注技术质量，还要关注业务价值。\\n  - Error（错误）/ Defect（缺陷）/ Failure（失效）— 人为失误(Error)在代码中引入缺陷(Defect)，执行到缺陷时触发失效(Failure)，三者是因果链\\n  - 测试退出准则 — 什么时候算测够了：覆盖率达标 / 缺陷收敛 / 风险可控 / 时间或预算耗尽\\n### 质量模型\\n- 软件质量通用的质量评估（ISO 25010）\\n  - 功能性：该有的功能都有，而且正确吗？\\n  - 性能效率：响应够快、资源占用合理吗？\\n  - 安全性：数据保密、防篡改、可审计吗？\\n  - 兼容性：能和其他系统共存、互操作吗？\\n  - 易用性：用户好上手吗？A11y(Accessibility（无障碍/可访问性）)无障碍到位吗？\\n  - 可靠性：故障率多低？宕机能多快恢复？\\n  - 可维护性：改起来痛苦吗？能模块化复用吗？\\n  - 可移植性：换平台/换环境的代价有多高？\\n- 测试金字塔\\n  - 单元测试（底座）：大量验证单个函数/方法，快，稳定，定位精确\\n  - 集成测试（中层）：中等量，验证模块间的契约，API / DB / 第三方服务\\n  - UI / 端到端测试（顶层）：少量，验证关键用户旅程\\n### 缺陷管理\\n- 缺陷生命周期（提交→确认→修复→验证→关闭），期间可能会多次回滚\\n  - 确认环节是质检——提交的 Bug 中总有「不是 Bug」「重复」「环境问题」的，这一步筛掉噪音\\n  - 挂起不等于关闭——通常是依赖第三方修复、或排期靠后的低优先级 Bug\\n  - 重开要追溯原因：是修错了、漏提交、还是修 A 炸了 B\\n- 严重度 vs 优先级\\n  - 严重程度一般是技术影响，典型的崩溃、数据丢失、安全漏洞，当然，页面logo错误也算是低严重性，严重性看Bug有多大\\n  - 优先级主要是对业务的影响，常见的核心流程阻断、线上事故，优先级主要看Bug有多急\\n- 根因分析（5 Why / 鱼骨图）\\n  - 5 Why（Bug：登录页提交报 500）\\n    - 为什么报 500？→ 后端接口抛 NullPointerException\\n    - 为什么 NPE(NullPointerException（空指针异常）)？→ session 里拿不到用户对象\\n    - 为什么拿不到？→ Redis 挂了，session 没持久化\\n    - 为什么 Redis 挂会影响？→ 没有降级逻辑，依赖是强耦合\\n    - 为什么没降级？→ 设计评审没覆盖异常路径\\n    - 根因：评审环节缺少异常场景 checklist，而不只是「修一下 NPE」\\n  - 鱼骨图（石川图） — 从人、机、料、法、环、测 6 个维度排查，适合复杂问题的可视化归因。\\n\\n## 测试分类\\n### 按测试级别分（Test Levels）\\n- 单元测试（组件级，JUnit / pytest / Jest）\\n- 集成测试（组件间集成 → 系统间集成）\\n- 系统测试（端到端全链路，含功能+非功能）\\n- 验收测试（UAT / Alpha / Beta / 合同验收 / 法规验收 / 运营验收 OAT）\\n### 按测试类型分（Test Types）\\n- 功能测试 — 验证\\"做对了该做的事\\"\\n- 非功能测试（对应 ISO 25010 质量属性）\\n  - 性能测试（负载 / 压力 / 稳定性 / 容量 / 并发）\\n  - 安全测试（渗透 / 漏洞扫描 / SAST / DAST）\\n  - 兼容性测试（多浏览器 / OS / 设备 / 网络 / 分辨率）\\n  - 易用性测试（用户体验 / A11y 无障碍）\\n  - 可靠性测试（故障恢复 / 容错 / 长稳）\\n  - 可移植性测试（多平台 / 多环境迁移）\\n  - 可维护性测试（代码规范 / 文档完整性）\\n- 结构测试（白盒，关注覆盖率和结构度量）\\n- 变更相关测试（确认测试 + 回归测试，详见下方「按测试目的分」）\\n### 按测试目的分\\n- 冒烟测试 — 验证构建基本可用，决定是否接受进入下一阶段\\n- 健全性测试 — 针对特定修复/变更的窄而深快速验证，确认改动生效\\n- 回归测试 — 验证代码变更未破坏已有功能\\n- 确认测试（再测试）— 验证已修复缺陷是否真的修好了\\n- 探索性测试 — 边学习边设计边执行，靠经验和直觉发现未知问题\\n### 按测试技术分（Test Techniques）\\n- 黑盒测试 — 基于规格说明，不看内部实现\\n- 白盒测试 — 基于代码结构，关注内部逻辑\\n- 灰盒测试 — 介于两者之间（如知道接口定义但不知实现）\\n- 基于经验的技术（探索性测试 / 错误推测 / 基于风险的测试 RBT）\\n### 按执行形态分\\n- 静态测试 — 不执行代码（需求评审 / 代码走查 / 静态分析）\\n- 动态测试 — 执行代码验证行为\\n### 按执行主体分\\n- 手工测试（探索性 / Ad-hoc / 基于会话的测试 SBTM）\\n- 自动化测试（脚本化 / 数据驱动 / 关键字驱动）\\n\\n## 测试设计方法\\n### 黑盒技术\\n- 等价类划分 — 把输入数据按等价特征分组，每组取代表值，减少冗余用例\\n- 边界值分析 — 在等价类边界和紧邻边界处设计用例，边界最容易出 Bug\\n- 决策表 — 用表格列出条件组合与对应动作，适合复杂业务规则\\n- 状态转换图 — 画出系统状态及触发条件，验证状态迁移的正确性\\n- 正交试验法 — 用正交表筛选多因素组合，最少用例覆盖两两交互\\n- 场景法 — 模拟用户真实业务流程，串联多步骤验证端到端路径\\n- 因果图 — 从需求中提取因（条件）果（结果）关系，转化为判定表的中间步骤\\n### 白盒技术\\n- 语句覆盖 — 确保每行代码至少执行一次，最基础的覆盖率指标\\n- 分支覆盖 — 每个判断的真假分支都走一遍\\n- 条件覆盖 — 每个子条件独立取真取假各一次\\n- 条件/判定覆盖 — 分支覆盖+条件覆盖的组合，同时满足判定和条件覆盖要求\\n- 路径覆盖 — 覆盖所有可能执行路径，组合爆炸实践中很少 100%\\n- MC/DC（修正条件判定覆盖）— 航空/安全关键系统强制要求，每个条件独立影响判定结果\\n### 经验技术\\n- 探索性测试（SBTM）— 边学边测，基于会话管理，同时设计执行学习\\n- 错误推测法 — 根据经验猜测哪里最可能出错，针对性设计用例\\n- 基于风险的测试（RBT）— 按风险等级（概率 × 影响）排优先级，高风险重点覆盖\\n\\n## 测试工具生态\\n### 自动化框架\\n- 单元测试\\n  - JUnit（Java）\\n  - pytest / unittest（Python）\\n  - Jest / Vitest（JavaScript/TypeScript）\\n  - NUnit / xUnit（.NET）\\n  - Go testing（Go）\\n- Web UI\\n  - Playwright\\n  - Selenium\\n  - Cypress\\n  - Puppeteer\\n- 移动端\\n  - Appium\\n  - XCTest（iOS）\\n  - Espresso（Android）\\n  - Detox（React Native 灰盒）\\n  - Maestro（轻量级跨平台）\\n- API\\n  - Postman（手工调试 + 自动化 + Mock）\\n  - RestAssured\\n  - pytest + requests / httpx（Python 接口自动化首选）\\n  - Supertest\\n  - SoapUI（企业级 SOAP/REST）\\n  - Karate（BDD 风格 API 自动化）\\n- 桌面端\\n  - WinAppDriver\\n  - SikuliX\\n### 性能工具\\n- JMeter\\n- Gatling\\n- k6\\n- Locust\\n- wrk（轻量 HTTP 压测）\\n- Artillery（场景化压测，支持 WebSocket）\\n- 监控：Prometheus + Grafana\\n### 抓包/代理工具\\n- Charles\\n- Fiddler\\n- Wireshark\\n- mitmproxy\\n- Proxyman\\n### 安全工具\\n- 渗透测试：Burp Suite / OWASP ZAP\\n- 漏洞扫描：SQLMap / Nessus\\n- SAST（静态应用安全测试）：Checkmarx / Fortify\\n- DAST（动态应用安全测试）：OWASP ZAP / Acunetix\\n- 依赖扫描：Snyk / OWASP Dependency-Check\\n### 代码质量 / 静态分析\\n- SonarQube / SonarLint\\n- ESLint / Prettier / StyleCop\\n- 复杂度分析：Lizard / Radon\\n### 云测平台\\n- BrowserStack / Sauce Labs（跨浏览器兼容性）\\n- LambdaTest / 阿里云移动测试\\n### Mock 工具\\n- WireMock（HTTP Mock 服务）\\n- Mockoon（桌面 GUI Mock）\\n- JSON Server（REST API 快速 Mock）\\n### BDD 框架\\n- Cucumber（多语言支持）\\n- SpecFlow（.NET 生态）\\n- Behave（Python 生态）\\n- Gauge（轻量级，Markdown 语法）\\n### 测试环境\\n- Docker / Docker Compose\\n- Selenium Grid / Selenoid\\n- Kubernetes（测试集群）\\n### CI/CD 集成\\n- Jenkins / GitHub Actions / GitLab CI\\n- 报告：Allure / ExtentReports\\n### 测试管理平台\\n- Jira+Xray / TestLink / TestRail\\n- 禅道 / TAPD\\n\\n## 测试全生命周期\\n### 需求阶段\\n- 需求评审\\n- 测试策略制定\\n### 计划阶段\\n- 测试计划 / 资源估算 / 进度安排\\n### 设计阶段\\n- 用例编写 / 数据准备 / 环境搭建\\n### 执行阶段\\n- 执行用例 / Bug提交 / 回归验证\\n### 评估阶段\\n- 测试报告 / 质量评估 / 复盘\\n### 上线与监控\\n- 线上冒烟 / 巡检 / 用户反馈闭环\\n\\n## 自动化测试体系\\n### 架构设计\\n- 分层架构（Base / PO / Test）\\n- Page Object Model（POM）\\n- Screenplay 模式\\n### 测试策略\\n- TDD（测试驱动开发）— 先写测试再写代码，红→绿→重构循环\\n- BDD（行为驱动开发）— 用自然语言描述行为，Given-When-Then 格式\\n- ATDD（验收测试驱动开发）— 团队共同定义验收标准再开发\\n### Test Doubles（测试替身）\\n- Mock — 预设期望，验证是否按预期调用\\n- Stub — 返回固定值，不关心是否被调用\\n- Spy — 记录调用信息，事后验证\\n- Fake — 真实对象的轻量替代（如内存数据库）\\n- Dummy — 仅用于填充参数，实际不会被用到\\n### 数据管理\\n- 数据驱动（JSON / Excel / CSV）\\n- 关键字驱动\\n- 测试数据工厂 / Faker\\n### 稳定性保障\\n- 等待策略（显式 / 隐式 / Fluent Wait）\\n- 失败处理（重跑 / 截图 / 录像）\\n- 用例独立性 & 原子性\\n### 持续测试\\n- 每日构建 + 自动化冒烟\\n- 分支策略触发\\n- 通知渠道（钉钉 / 飞书 / 企微 / 邮件）\\n\\n## 专项测试\\n### 移动端专项\\n- 弱网测试（Charles / Fiddler）\\n- 电量 / 内存泄漏\\n- 多分辨率适配\\n### 数据测试\\n- 数据库校验（SQL断言）\\n- ETL / 数据迁移测试\\n### 契约测试\\n- Pact / Spring Cloud Contract\\n### AI / 大模型测试\\n- 准确性评估（RAGAS / 人工评分）\\n- 安全性（Prompt注入 / 越狱）\\n- 稳定性（幻觉率 / 输出一致性）\\n### 混沌工程\\n- Chaos Monkey / Chaos Mesh / Litmus\\n- 故障注入：网络延迟 / CPU 打满 / Pod 随机删除\\n- Game Day 演练 — 模拟生产故障演练团队响应\\n### 灰度 / 金丝雀发布\\n- 灰度策略：百分比 / 地域 / 用户画像分流\\n- 金丝雀分析：对比新旧版本指标自动判定\\n- 线上监控验证：错误率 / 延迟 / 业务指标实时对比\\n### 本地化 / 国际化测试（i18n / l10n）\\n- 多语言覆盖（翻译完整性 / 截断 / 布局适配）\\n- 日期/时间/货币/数字格式\\n- 字符编码（Unicode / 双向文本 RTL）\\n- 文化适配（图标 / 颜色 / 法律合规）\\n\\n## 行业实践与软技能\\n### 敏捷 / DevOps 中的测试\\n- 左移测试（Shift-Left）\\n- 右移测试（Shift-Right）\\n### 测试思维\\n- 批判性思维\\n- 用户视角 vs 技术视角\\n- 数据敏感度\\n### 沟通协作\\n- Bug 描述技巧\\n- 测试报告写作\\n- 跨角色协作\\n### 质量内建\\n- 代码评审中的测试视角（可测试性 / 边界条件 / 异常路径）\\n- 质量度量（缺陷密度 / 逃逸率 / MTBF / 测试通过率）\\n- 持续改进（回顾会 / 缺陷根因闭环）\\n\\n## 学习路径\\n### 推荐书籍\\n- 《软件测试的艺术》\\n- 《Google软件测试之道》\\n- 《软件测试》\\n"},"headers":[],"relativePath":"knowledge-graph/software-testing/index.md","filePath":"知识图谱/5.软件测试.md","lastUpdated":1782289777000}'),i={name:"knowledge-graph/software-testing/index.md"};function r(c,p,l,u,S,d){const n=t("MindmapPage");return s(),a("div",null,[o(n)])}const A=e(i,[["render",r]]);export{P as __pageData,A as default};
